			{3,2,6,7}, {2,0,4,6},
		}
	);

	for (auto &edge : mesh.edges) {
		edge.sharp = true;
	}
	mesh.set_corner_normals(0.0f);
	mesh.set_corner_uvs_per_face();

	return mesh;
}

