std::optional<Halfedge_Mesh::VertexRef> Halfedge_Mesh::bisect_edge(EdgeRef e) {
	// Phase 0: draw a picture
	//
	// before:
	//    ----h--->
	// v1 ----e---- v2
	//   <----t----
	//
	// after:
	//    --h->    --h2->
	// v1 --e--- vm --e2--- v2
	//   <-t2-    <--t--
	//

	// Phase 1: collect existing elements
	HalfedgeRef h = e->halfedge;
	HalfedgeRef t = h->twin;
	VertexRef v1 = h->vertex;
	VertexRef v2 = t->vertex;

	// Phase 2: Allocate new elements, set data
	VertexRef vm = emplace_vertex();
	vm->position = 0.5f * (v1->position + v2->position);
	interpolate_data({v1, v2}, vm); //set bone_weights on the new vertex

	EdgeRef e2 = emplace_edge(e->sharp); //the second half is as sharp as the original

	HalfedgeRef h2 = emplace_halfedge();
	interpolate_data({h, h->next}, h2); //set corner_uv, corner_normal (h2's corner sits between h's and h->next's)

	HalfedgeRef t2 = emplace_halfedge();
	interpolate_data({t, t->next}, t2); //set corner_uv, corner_normal

	// Phase 3: Reassign connectivity (careful about ordering so you don't overwrite values you may need later!)

	vm->halfedge = h2; //vm's halfedge lies along the original edge

	e2->halfedge = h2;
	//e->halfedge remains h

	//h2 takes over the second half of h's old span:
	h2->set_tnvef(t, h->next, vm, e2, h->face);
	//t2 takes over the second half of t's old span:
	t2->set_tnvef(h, t->next, vm, e, t->face);

	//h keeps its vertex (v1), edge (e) and face, but now stops at vm:
	h->twin = t2;
	h->next = h2;

	//t keeps its vertex (v2) and face, but is now half of e2 and stops at vm:
	t->twin = h2;
	t->next = t2;
	t->edge = e2;

	//v1->halfedge (possibly h) and v2->halfedge (possibly t) still leave the
	// same vertices, so no vertex fixups are needed.
	//h and t also stay in their faces, so no face fixups are needed.

	// Phase 4: Delete unused elements
	//(none: bisect_edge only adds things)

	// Phase 5: Return the correct iterator
	return vm;
}

