Test test_a2_agent_bisect_edge_interior("a2.agent.bisect_edge.interior", []() {
	Halfedge_Mesh mesh = quad_tri();
	//edge 1-4 (interior, between the quad and the triangle):
	Halfedge_Mesh::EdgeRef edge = mesh.halfedges.begin()->next->next->edge;

	size_t nv = mesh.vertices.size(), ne = mesh.edges.size();
	size_t nf = mesh.faces.size(), nh = mesh.halfedges.size();

	auto ret = mesh.bisect_edge(edge);
	if (!ret) throw Test::error("bisect_edge rejected an interior edge!");
	check_valid(mesh, "bisect_edge.interior");

	if (mesh.vertices.size() != nv + 1) throw Test::error("bisect_edge should add exactly one vertex.");
	if (mesh.edges.size() != ne + 1) throw Test::error("bisect_edge should add exactly one edge.");
	if (mesh.faces.size() != nf) throw Test::error("bisect_edge should not add faces.");
	if (mesh.halfedges.size() != nh + 2) throw Test::error("bisect_edge should add exactly two halfedges.");

	Halfedge_Mesh::VertexRef vm = ret.value();
	if (Test::differs(vm->position, Vec3(1.25f, 0.0f, 0.0f))) {
		throw Test::error("bisect_edge should place the new vertex at the edge midpoint.");
	}
	if (vm->degree() != 2) throw Test::error("the bisecting vertex should have degree two.");
	//the returned vertex's halfedge should lie along the original edge:
	if (vm->halfedge->twin->vertex != vm->halfedge->next->vertex &&
	    vm->halfedge->edge != edge) {
		//(only a sanity check that halfedge is set at all)
	}

	Halfedge_Mesh after = Halfedge_Mesh::from_indexed_faces({
		Vec3(-1.0f, 1.1f, 0.0f), Vec3(1.1f, 1.0f, 0.0f),
		                         Vec3(1.25f, 0.0f, 0.0f), Vec3(2.2f, 0.0f, 0.0f),
		Vec3(-1.3f,-0.7f, 0.0f), Vec3(1.4f, -1.0f, 0.0f)
	}, {
		{0, 4, 5, 2, 1},
		{1, 2, 5, 3}
	});
	if (auto diff = Test::differs(mesh, after, Test::CheckAllBits)) {
		throw Test::error("bisect_edge result did not match expected: " + *diff);
	}
});

/*
 * bisecting a boundary edge should grow the boundary loop, not split it.
 */
Test test_a2_agent_bisect_edge_boundary("a2.agent.bisect_edge.boundary", []() {
	Halfedge_Mesh mesh = quad_tri();
	//edge 0-1 (on the boundary):
	Halfedge_Mesh::EdgeRef edge = mesh.halfedges.begin()->next->next->next->edge;

	size_t boundaries = mesh.n_boundaries();

	auto ret = mesh.bisect_edge(edge);
	if (!ret) throw Test::error("bisect_edge rejected a boundary edge!");
	check_valid(mesh, "bisect_edge.boundary");
	if (mesh.n_boundaries() != boundaries) throw Test::error("bisect_edge changed the number of boundary loops.");

	Halfedge_Mesh after = Halfedge_Mesh::from_indexed_faces({
		Vec3(-1.0f, 1.1f, 0.0f), Vec3(0.05f, 1.05f, 0.0f), Vec3(1.1f, 1.0f, 0.0f),
		                                            Vec3(2.2f, 0.0f, 0.0f),
		Vec3(-1.3f,-0.7f, 0.0f), Vec3(1.4f, -1.0f, 0.0f)
	}, {
		{0, 4, 5, 2, 1},
		{2, 5, 3}
	});
	if (auto diff = Test::differs(mesh, after, Test::CheckAllBits)) {
		throw Test::error("bisect_edge result did not match expected: " + *diff);
	}
});

/*
 * bisecting every edge of a cube should keep it valid and preserve its shape.
 */
Test test_a2_agent_bisect_edge_cube("a2.agent.bisect_edge.cube", []() {
	Halfedge_Mesh mesh = Halfedge_Mesh::cube(1.0f);
	std::vector<Halfedge_Mesh::EdgeRef> original;
	for (Halfedge_Mesh::EdgeRef e = mesh.edges.begin(); e != mesh.edges.end(); ++e) original.emplace_back(e);

	for (Halfedge_Mesh::EdgeRef e : original) {
		if (!mesh.bisect_edge(e)) throw Test::error("bisect_edge rejected a cube edge!");
	}
	check_valid(mesh, "bisect_edge.cube");
	if (mesh.vertices.size() != 8 + 12) throw Test::error("bisecting all cube edges should give 20 vertices.");
	if (mesh.edges.size() != 24) throw Test::error("bisecting all cube edges should give 24 edges.");
	if (mesh.faces.size() != 6) throw Test::error("bisecting all cube edges should not change the face count.");
	for (Halfedge_Mesh::FaceRef f = mesh.faces.begin(); f != mesh.faces.end(); ++f) {
		if (f->degree() != 8) throw Test::error("every cube face should be an octagon after bisecting all edges.");
	}
});
